public class MultiplePiePlot_MultiplePiePlot_TriageGen0Test {

    @Test
    public void testConstructorWithDataset() {
        // Arrange
        CategoryDataset mockDataset = mock(CategoryDataset.class);

        // Act
        MultiplePiePlot plot = new MultiplePiePlot(mockDataset);

        // Assert
        // Check if dataset is set correctly
        assertEquals(mockDataset, plot.getDataset());

        // Check if pieChart is initialized and configured
        JFreeChart chart = plot.getPieChart();
        assertNotNull("PieChart should not be null", chart);
        assertNull("Background paint should be null", chart.getBackgroundPaint());
        assertFalse("Legend should be removed", chart.getLegend().isVisible());

        // Check Title configuration
        TextTitle title = (TextTitle) chart.getTitle();
        assertNotNull("Title should not be null", title);
        assertEquals("Series Title", title.getText());
        assertEquals(Font.SANS_SERIF, title.getFont().getFamily());
        assertEquals(Font.BOLD, title.getFont().getStyle());
        assertEquals(12, title.getFont().getSize());

        // Check internal state defaults
        assertEquals(TableOrder.BY_COLUMN, plot.getDataExtractOrder());
        assertEquals("Other", plot.getAggregatedItemsKey().toString());
        assertEquals(Color.lightGray, plot.getAggregatedItemsPaint());
    }

    @Test
    public void testConstructorWithNullDataset() {
        // Arrange
        CategoryDataset nullDataset = null;

        // Act
        MultiplePiePlot plot = new MultiplePiePlot(nullDataset);

        // Assert
        assertNull(plot.getDataset());
        assertNotNull(plot.getPieChart());
    }

    @Test
    public void testDefaultConstructor() {
        // Act
        MultiplePiePlot plot = new MultiplePiePlot();

        // Assert
        // Since the default constructor is defined but its body isn't provided in the snippet,
        // we assume it at least initializes the object. 
        // If it calls the parameterized constructor, we verify basic non-nullity.
        assertNotNull(plot);
    }

    @Test
    public void testSettersAndGetters() {
        // Arrange
        MultiplePiePlot plot = new MultiplePiePlot();
        CategoryDataset mockDataset = mock(CategoryDataset.class);
        JFreeChart mockChart = mock(JFreeChart.class);
        TableOrder newOrder = TableOrder.BY_ROW;
        double newLimit = 5.5;
        String newKey = "NewKey";
        Color newPaint = Color.RED;

        // Act & Assert
        plot.setDataset(mockDataset);
        assertEquals(mockDataset, plot.getDataset());

        plot.setPieChart(mockChart);
        assertEquals(mockChart, plot.getPieChart());

        plot.setDataExtractOrder(newOrder);
        assertEquals(newOrder, plot.getDataExtractOrder());

        plot.setLimit(newLimit);
        assertEquals(newLimit, plot.getLimit(), 0.001);

        plot.setAggregatedItemsKey(newKey);
        assertEquals(newKey, plot.getAggregatedItemsKey());

        plot.setAggregatedItemsPaint(newPaint);
        assertEquals(newPaint, plot.getAggregatedItemsPaint());
    }
}
